gb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">t t_capital</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">begin&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">t(1) := 'abc'; t(2) := 'zxcv'</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;"><br></span></div><div><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">DECLARE</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp; TYPE t_num_list&nbsp;</span><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">IS</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">TABLE</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">OF</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;NUMBER;&nbsp;</span><span class="hljs-comment" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">-- Nested table declaration</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp; v_numbers t_num_list :</span><span class="hljs-operator" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">=</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">t_num_list();&nbsp;</span></div><div><span class="hljs-comment" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">-- Initialized constructor</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">BEGIN</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp; v_numbers.EXTEND(</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">2</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">);&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">v_numbers(</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">1</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">) :</span><span class="hljs-operator" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">=</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">10</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;v_numbers(</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">2</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">) :</span><span class="hljs-operator" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">=</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">20</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">;&nbsp;</span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">v_numbers.DELETE(</span><span class="hljs-number" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">1</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">);&nbsp;</span><span class="hljs-comment" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">-- Index 1 is deleted; collection is now sparse</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">&nbsp;</span></div><div><span class="hljs-keyword" style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); white-space: normal;">END</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;">;</span><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;"><br></span></div><div><span style="caret-color: rgb(0, 0, 0); color: rgb(0, 0, 0); font-family: -webkit-standard; white-space: normal;"><br></span></div><div><div>DECLARE</div><div>&nbsp; &nbsp; TYPE t_phones IS VARRAY(3) OF VARCHAR2(15); -- Fixed max size of 3</div><div>&nbsp; &nbsp; v_my_phones t_phones := t_phones('555-0100', '555-0199'); -- Initialized</div><div>BEGIN</div><div>&nbsp; &nbsp; v_my_phones.EXTEND;</div><div>&nbsp; &nbsp; v_my_phones(3) := '555-0288';</div><div>&nbsp; &nbsp;&nbsp;&nbsp; &nbsp; -- v_my_phones.EXTEND; -- RAISES ERROR: Exceeds VARRAY limit of 3</div><div>END;</div><div>/</div></div><div><br></div><div>-- Step 1: Create the collection type at the schema level
CREATE OR REPLACE TYPE item_list_type AS TABLE OF NUMBER;
/

-- Step 2: Use the collection as a column data type in a table
CREATE TABLE customer_orders (
    order_id     NUMBER PRIMARY KEY,
    order_date   DATE,
    order_items  item_list_type -- Column holding a collection of numbers!
) NESTED TABLE order_items STORE AS order_items_store_tab;

desc customer_orders;   

INSERT INTO customer_orders (order_id, order_date, order_items)
VALUES (    103, SYSDATE, NULL -- The entire collection object is NULL
);

SELECT order_id, order_date, order_items   FROM customer_orders;

  INSERT INTO customer_orders (order_id, order_date, order_items)
VALUES (101, SYSDATE, item_list_type(5001, 5002, 5003) -- Constructor populates the collection
);

INSERT INTO customer_orders (order_id, order_date, order_items)
VALUES (102, SYSDATE, item_list_type() -- Empty collection (NOT NULL, but holds 0 elements)
);

SELECT c.order_id, 
       c.order_date, 
       t.COLUMN_VALUE AS item_id
  FROM customer_orders c,
       TABLE(c.order_items) t;<br></div><div><br></div><div><br></div><div>--Varrya</div><div>-- Create a type that holds up to 3 phone numbers
CREATE OR REPLACE TYPE phone_list_type AS VARRAY(3) OF VARCHAR2(15);
/<br></div><div>CREATE TABLE customer_contacts (
    customer_id   NUMBER PRIMARY KEY,
    customer_name VARCHAR2(50),
    phone_numbers phone_list_type -- VARRAY column
);<br></div><div>-- 1. Insert 2 phone numbers
INSERT INTO customer_contacts (customer_id, customer_name, phone_numbers)
VALUES (
    1, 
    'Alice Smith', 
    phone_list_type('555-0100', '555-0101')
);

-- 2. Insert 3 phone numbers (Maximum limit)
INSERT INTO customer_contacts (customer_id, customer_name, phone_numbers)
VALUES (
    2, 
    'Bob Jones', 
    phone_list_type('555-0200', '555-0201', '555-0202')
);
-- 3. Attempting to insert 4 items raises ORA-06532: Subscript outside of limit
-- INSERT INTO customer_contacts VALUES (3, 'Charlie', phone_list_type('1','2','3','4'));

COMMIT;<br></div>
